function editrowcomp_A_Good_data(i) {

    $('#AWP1_TR_data' + i).hide();
    $('#Hide_AWP1_TR_data' + i).show();
}
function cancelcomp_A_Support_NEW_data(i) {

    $('#AWP1_TR_data' + i).show();
    $('#Hide_AWP1_TR_data' + i).hide();

}
function Update_data_data(ss, RowNo) {

    var i = 0;
    var id = ss;
    var gwl_reading = $('#gwl_reading' + RowNo).val();

    if (gwl_reading == "") {

        alert("Please Enter Ground Water Level Reading ");
        i = 1;
    }
    if (i == 0) {


        var formdata = new FormData();
        formdata.append("id", id);
        formdata.append("gwl_reading", gwl_reading);

        $.ajax({
            url: '/GplevelMobileData/Update_gwl_data',
            data: formdata,
            type: 'POST',
            contentType: false,
            processData: false,
            success: function (response) {

                alert(response);
                if (response == "SessionTimeOut") {
                    window.location = "/WspNew/WSP_GWM_HOME";
                }
                else if (response == "Updated Successfully") {
                    find_exi_data(idd);
                } else {
                    $('.loader').hide();
                }
            },
            error: function () {
                alert('Update Failed');
            }
        });
    }
}
function Delete_gwl_data(ss) {
    if (confirm("Are you sure you want to delete this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_gwl_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);

                if (response == "Logout") {
                    window.location = "/WspNew/WSP_GWM_HOME";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_exi_data(idd);
            }
        });
    }
}
function submit_spmu_gwl_data(ss) {

    var obj = {};
    obj.id = ss;
    $.ajax({
        type: "POST",
        contentType: "application/json;charset=utf-8",
        url: "/GplevelMobileData/submit_spmu_gwl_data",
        data: "{'Data': '" + JSON.stringify(obj) + "'}",
        dataType: 'JSON',
        success: function (response) {
            alert(response);
            if (response == "Logout") {
                window.location = "/WspNew/WSP_GWM_HOME";
            }
            else if (response != "Successfully Submited" && response != "Logout" && response != "No Data") {
                window.location = "/Error/DefaultError";
            }

            find_exi_data(idd);
        }
    });

}
function approve_spmu_gwl_data(ss) {

    var obj = {};
    obj.id = ss;
    $.ajax({
        type: "POST",
        contentType: "application/json;charset=utf-8",
        url: "/GplevelMobileData/approve_gwl_data",
        data: "{'Data': '" + JSON.stringify(obj) + "'}",
        dataType: 'JSON',
        success: function (response) {
            alert(response);
            if (response == "Logout") {
                window.location = "/WspNew/WSP_GWM_HOME";
            }
            else if (response != "Approved Successfully" && response != "Logout" && response != "No Data") {
                window.location = "/Error/DefaultError";
            }

            find_exi_data(idd);
        }
    });

}

