var totalwaterflow = 0;
function watertotal() {

    $('.loader').show();

    var year = $('#year').val();
    var month = $('#month').val();
    var obj = {};
    obj.statename = State;
    obj.districtname = Dist;
    obj.blockname = Block;
    obj.gpname = Gram;
    obj.PageNumber = PageNumber;
    $.ajax({
        type: 'POST',
        contentType: 'application/json; chatset=utf-8',
        url: '/GplevelMobileData/totalwaterflow',
        data: "{'Data': '" + JSON.stringify(obj) + "', 'month1':'" + month + "' , 'year1':'" + year + "'}",
        dataType: 'JSON',

        success: function (data) {
            if (data == 'Logout') {
                window.location = "/WspNew/WSP_GWM_HOME";
            }
            var data = data.split(',');
            $('#watertotal').text(data[0]);
            $('#totalwater').text(data[1]);
            $('#total_gp_waterflow').text(data[2]);
            totalwaterflow = data[1];
            if (totalwaterflow == PageNumber_waterflow || totalwaterflow == 0) {
                $('#btnnext_water').hide();
                
            }
            else {
                $('#btnnext_water').show();
            }
            var dgshfgshd = data[0];
            if (dgshfgshd == 0) {
                $('#pdfwater').prop('disabled', true);
            }
            else {
                $('#pdfwater').prop('disabled', false);
            }
            if (totalwaterflow==1) {
                PageNumber_waterflow = 1;
            }
            $('#btnsubmit_water').prop('disabled', false);

            watreflow();
        }
    });

}
function total_gp_waterflow() {

    $('.loader').show();
    var year = $('#year').val();
    var month = $('#month').val();

    var obj = {};
    obj.statename = State;
    obj.districtname = Dist;
    obj.blockname = Block;
    obj.gpname = Gram;
    obj.year = year;
    obj.month = month;
    $.ajax({
        type: 'POST',
        contentType: 'application/json; chatset=utf-8',
        url: '/GplevelMobileData/total_gp_waterflow',
        data: "{'Data': '" + JSON.stringify(obj) + "'}",
        dataType: 'JSON',
        success: function (data) {

            var data = data;

            if (data == 'No Data') {
                $('#total_gp_waterflow').text(0);

            }
            else {
                $('#total_gp_waterflow').text(data);
            }
            /*sno_waterflow = 0;*/
            watreflow();
        },
        error: function () {

        }
    });
}

