function Delete_rainfall(ss) {
    if (confirm("Are you sure you want to delete this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_rainfall",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);
                click_rainfall += 1;
                if (response == "Logout") {
                    window.location = "/WspNew/WSP_GWM_HOME";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }
                PageNumber_rain = PageNumber_rain;
                if (PageNumber_rain == 1) {
                    sno_rain = 0;
                    countrain = 0;
                } else {
                    var ssd = (PageNumber_rain - 1);
                    var sdsd = ssd * 100;
                    sno_rain = sdsd;
                }

                //sno_rain = 0;
                //countrain = 0;
                totalrainss = 0;
                raintotal();
            }
        });
    }
}
function submit_spmu_rainfall(ss) {

    var obj = {};
    obj.id = ss;
    $.ajax({
        type: "POST",
        contentType: "application/json;charset=utf-8",
        url: "/GplevelMobileData/submit_spmu_rainfall",
        data: "{'Data': '" + JSON.stringify(obj) + "'}",
        dataType: 'JSON',
        success: function (response) {
            alert(response);
            if (response == "Logout") {
                window.location = "/WspNew/WSP_GWM_HOME";
            }
            else if (response != "Successfully Submited" && response != "Logout" && response != "No Data") {
                window.location = "/Error/DefaultError";
            }
            PageNumber_rain = PageNumber_rain;
            if (PageNumber_rain == 1) {
                sno_rain = 0;
                countrain = 0;
            } else {
                var ssd = (PageNumber_rain - 1);
                var sdsd = ssd * 100;
                sno_rain = sdsd;
            }
            //PageNumber_rain = 1;
            //sno_rain = 0;
            //countrain = 0;
            totalrainss = 0;
            raintotal();
        }
    });

}
function approve_spmu_rainfall(ss) {

    var obj = {};
    obj.id = ss;
    $.ajax({
        type: "POST",
        contentType: "application/json;charset=utf-8",
        url: "/GplevelMobileData/approve_rainfall",
        data: "{'Data': '" + JSON.stringify(obj) + "'}",
        dataType: 'JSON',
        success: function (response) {
            alert(response);
            if (response == "Logout") {
                window.location = "/WspNew/WSP_GWM_HOME";
            }
            else if (response != "Approved Successfully" && response != "Logout" && response != "No Data") {
                window.location = "/Error/DefaultError";
            }
            PageNumber_rain = PageNumber_rain;
            if (PageNumber_rain == 1) {
                sno_rain = 0;
                countrain = 0;
            } else {
                var ssd = (PageNumber_rain - 1);
                var sdsd = ssd * 100;
                sno_rain = sdsd;
            }
            //PageNumber_rain = 1;
            //sno_rain = 0;
            //countrain = 0;
            totalrainss = 0;
            raintotal();
        }
    });

}
