function Update_data_rainfall(id, RowNo) {

    var i = 0;
    var id = id;
    var latitude = $('#latitude_rain' + RowNo).val();
    var longitude = $('#longitude_rain' + RowNo).val();
    var village = $('#village' + RowNo).val();
    var locationdetail = $('#locationdetail' + RowNo).val();

    if (latitude == "") {
        alert("Please Enter latitude");
        i = 1;
    }
    else if (longitude == "") {

        alert("Please Enter longitude");
        i = 1;
    }
    else if (village == "" || village == null) {

        alert("Please Enter Village Name");
        i = 1;
    }
    else if (locationdetail == "" || locationdetail == null) {

        alert("Please Enter Location Details");
        i = 1;
    }

    if (i == 0) {


        var formdata = new FormData();
        formdata.append("id", id);
        formdata.append("village", village);
        formdata.append("locationdetail", locationdetail);
        formdata.append("latitude", latitude);
        formdata.append("longitude", longitude);

        $.ajax({
            url: '/GplevelMobileData/Update_rainfall',
            data: formdata,
            type: 'POST',
            contentType: false,
            processData: false,
            success: function (response) {

                alert(response);
                if (response == "SessionTimeOut") {
                    window.location = "/WspNew/WSP_GWM_HOME";
                }
                else if (response == "Updated Successfully") {
                    PageNumber_rain = PageNumber_rain;
                    if (PageNumber_rain == 1) {
                        sno_rain = 0;
                        countrain = 0;
                    } else {
                        var ssd = (PageNumber_rain - 1);
                        var sdsd = ssd * 100;
                        sno_rain = sdsd;
                    }
                    totalrainss = 0;
                    raintotal();
                }
            },
            error: function () {
                alert('Update Failed');
            }
        });
    }
}
function enforceNumberValidation_rainfall(i, ele) {

    let j = i.toString();
    /*var i = aaa;*/
    var match = false;
    var match2 = false;
    var matchwr = false;
    var matchwr2 = false;
    var lat = $('#latitude_rain' + j).val();
    var long = $('#longitude_rain' + j).val();

    if (!(lat.indexOf(".") == -1)) {
        match = true; // decimal
    } else {
        match = false;
    }
    if (lat.length == 2 && match != true) {
        $('#latitude_rain' + j).val(lat + '.');
    } else if (lat.length == 1 && match != false) {
        $('#latitude_rain' + j).val('');
    }


    if (!(long.indexOf(".") == -1)) {
        match2 = true; // decimal
    } else {
        match2 = false;
    }
    if (long.length == 2 && match2 != true) {
        $('#longitude_rain' + j).val(long + '.');
    } else if (long.length == 1 && match2 != false) {
        $('#longitude_rain' + j).val('');
    }


    var latwr = $('#latitude_rain' + j).val();
    var longwr = $('#longitude_rain' + j).val();

    if (!(latwr.indexOf(".") == -1)) {
        matchwr = true; // decimal
    } else {
        matchwr = false;
    }
    if (latwr.length == 2 && matchwr != true) {
        $('#latitude_rain' + j).val(latwr + '.');
    } else if (latwr.length == 1 && matchwr != false) {
        $('#latitude_rain' + j).val('');
    }


    if (!(longwr.indexOf(".") == -1)) {
        matchwr2 = true; // decimal
    } else {
        matchwr2 = false;
    }
    if (longwr.length == 2 && matchwr2 != true) {
        $('#longitude_rain' + j).val(longwr + '.');
    } else if (longwr.length == 1 && matchwr2 != false) {
        $('#longitude_rain' + j).val('');
    }


    if ($(ele).data('decimal') != null) {
        // found valid rule for decimal
        var decimal = parseInt($(ele).data('decimal')) || 0;
        var val = $(ele).val();
        if (decimal > 0) {
            var splitVal = val.split('.');
            if (splitVal.length == 2 && splitVal[1].length > decimal) {
                // user entered invalid input
                $(ele).val(splitVal[0] + '.' + splitVal[1].substr(0, decimal));
            }
        } else if (decimal == 0) {
            // do not allow decimal place
            var splitVal = val.split('.');
            if (splitVal.length > 1) {
                // user entered invalid input
                $(ele).val(splitVal[0]); // always trim everything after '.'
            }
        }
    }
}

