function editrowcomp_A_Good_rainfalldata(i) {

    $('#AWP1_TR_data_rainfall' + i).hide();
    $('#Hide_AWP1_TR_data_rainfall' + i).show();
}
function cancelcomp_A_Support_NEW_data_rainfall(i) {

    $('#AWP1_TR_data_rainfall' + i).show();
    $('#Hide_AWP1_TR_data_rainfall' + i).hide();

}
function Update_rainfall_data(ss, RowNo) {

    var i = 0;
    var id = ss;
    var rf_reading = $('#rf_reading' + RowNo).val();

    if (rf_reading == "") {

        alert("Please Enter Rainfall Reading ");
        i = 1;
    }
    if (i == 0) {


        var formdata = new FormData();
        formdata.append("id", id);
        formdata.append("rf_reading", rf_reading);

        $.ajax({
            url: '/GplevelMobileData/Update_rainfall_data',
            data: formdata,
            type: 'POST',
            contentType: false,
            processData: false,
            success: function (response) {

                alert(response);
                if (response == "SessionTimeOut") {
                    window.location = "/WspNew/WSP_GWM_HOME";
                }
                else if (response == "Updated Successfully") {
                    find_rainfall_data(iddrainfall);
                }
            },
            error: function () {
                alert('Update Failed');
            }
        });
    }
}
function Delete_railfall_data(ss) {
    if (confirm("Are you sure you want to delete this entry?")) {
        var obj = {};
        obj.id = ss;
        $.ajax({
            type: "POST",
            contentType: "application/json;charset=utf-8",
            url: "/GplevelMobileData/Delete_rainfall_data",
            data: "{'Data': '" + JSON.stringify(obj) + "'}",
            dataType: 'JSON',
            success: function (response) {
                alert(response);

                if (response == "Logout") {
                    window.location = "/WspNew/WSP_GWM_HOME";
                }
                else if (response != "Deleted Successfully" && response != "Logout" && response != "No Data") {
                    window.location = "/Error/DefaultError";
                }

                find_rainfall_data(iddrainfall);
            }
        });
    }
}
function submit_spmu_rainfall_data(ss) {

    var obj = {};
    obj.id = ss;
    $.ajax({
        type: "POST",
        contentType: "application/json;charset=utf-8",
        url: "/GplevelMobileData/submit_spmu_rainfall_data",
        data: "{'Data': '" + JSON.stringify(obj) + "'}",
        dataType: 'JSON',
        success: function (response) {
            alert(response);
            if (response == "Logout") {
                window.location = "/WspNew/WSP_GWM_HOME";
            }
            else if (response != "Successfully Submited" && response != "Logout" && response != "No Data") {
                window.location = "/Error/DefaultError";
            }

            find_rainfall_data(iddrainfall);
        }
    });

}
function approve_spmu_rainfall_data(ss) {

    var obj = {};
    obj.id = ss;
    $.ajax({
        type: "POST",
        contentType: "application/json;charset=utf-8",
        url: "/GplevelMobileData/approve_rainfall_data",
        data: "{'Data': '" + JSON.stringify(obj) + "'}",
        dataType: 'JSON',
        success: function (response) {
            alert(response);
            if (response == "Logout") {
                window.location = "/WspNew/WSP_GWM_HOME";
            }
            else if (response != "Approved Successfully" && response != "Logout" && response != "No Data") {
                window.location = "/Error/DefaultError";
            }

            find_rainfall_data(iddrainfall);
        }
    });

}
